target.css:
:root {
  --bg-card: #ffffff;
  --accent: #5b4ef8;
  --accent-light: #ede9ff;
  --text-primary: #1a1a2e;
  --text-secondary: #6b6b8a;
  --text-muted: #a0a0b8;
  --border: #e8e8f0;
  --row-alt: #f9f9fc;
  --badge-bg: #fff3cd;
  --badge-text: #7a5c00;
  --status-bg: #e8f5e9;
  --status-text: #2e7d32;
  --grand-bg: #5b4ef8;
  --grand-text: #ffffff;
}

body {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 100vh;
  margin: 0;
  padding: 20px;
  box-sizing: border-box;
}

.invoice-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 16px;
  padding: 20px 24px;
  width: 500px;
  max-width: 100%;
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.invoice-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.brand {
  display: flex;
  align-items: center;
  gap: 8px;
}

.brand-mark {
  color: var(--accent);
  font-size: 18px;
}

.brand-name {
  font-size: 18px;
  font-weight: 700;
  color: var(--text-primary);
  letter-spacing: -0.3px;
}

.invoice-meta {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 2px;
}

.invoice-label {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 1.5px;
  color: var(--text-muted);
}

.invoice-number {
  font-size: 15px;
  font-weight: 700;
  color: var(--accent);
}

.divider {
  height: 1px;
  background: var(--border);
  border-radius: 1px;
}

.client-row {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
}

.client-info,
.due-info {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.due-info {
  align-items: flex-end;
}

.field-label {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 1.2px;
  color: var(--text-muted);
  text-transform: uppercase;
}

.client-name {
  font-size: 15px;
  font-weight: 700;
  color: var(--text-primary);
}

.client-sub {
  font-size: 12px;
  color: var(--text-secondary);
}

.due-date {
  font-size: 15px;
  font-weight: 700;
  color: var(--text-primary);
}

.due-badge {
  font-size: 11px;
  font-weight: 600;
  background: var(--badge-bg);
  color: var(--badge-text);
  border-radius: 6px;
  padding: 2px 8px;
  text-align: center;
}

.line-items {
  display: flex;
  flex-direction: column;
  gap: 0;
  border: 1px solid var(--border);
  border-radius: 10px;
  overflow: hidden;
}

.line-item {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  padding: 8px 14px;
  font-size: 13px;
  color: var(--text-primary);
  background: var(--bg-card);
}

.line-item:nth-child(even) {
  background: var(--row-alt);
}

.line-item.header-row {
  background: var(--accent-light);
  font-size: 11px;
  font-weight: 700;
  color: var(--accent);
  letter-spacing: 0.5px;
  text-transform: uppercase;
}

.line-item span:not(:first-child) {
  text-align: right;
}

.totals-row {
  display: flex;
  justify-content: flex-end;
}

.totals-block {
  display: flex;
  flex-direction: column;
  gap: 4px;
  min-width: 200px;
}

.total-line {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 13px;
  color: var(--text-secondary);
  padding: 2px 0;
}

.total-line.grand {
  background: var(--grand-bg);
  color: var(--grand-text);
  font-size: 14px;
  font-weight: 700;
  padding: 8px 12px;
  border-radius: 8px;
  margin-top: 4px;
}

.invoice-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.status-badge {
  font-size: 12px;
  font-weight: 600;
  background: var(--status-bg);
  color: var(--status-text);
  border-radius: 20px;
  padding: 4px 12px;
}

.footer-note {
  font-size: 12px;
  color: var(--text-muted);
  font-style: italic;
}

